const body = $input.first().json.body || $input.first().json;
const rawUrl = (body.url || '').trim();
const startChapter = parseInt(body.start_chapter) || 1;
const endChapter = body.end_chapter ? parseInt(body.end_chapter) : null;

if (!rawUrl) {
  return [{ json: { status: 'error', error: 'Missing url in request body' } }];
}

let host;
try {
  const parsed = new URL(rawUrl);
  host = parsed.hostname.toLowerCase();
  if (host.startsWith('www.')) host = host.slice(4);
} catch (e) {
  return [{ json: { status: 'error', error: 'Invalid URL: ' + rawUrl } }];
}

const PLATFORMS = {
  'webnovel.com':     { platform: 'webnovel',     lang: 'en', needs_translation: false, scraper_type: 'http'  },
  '69shuba.com':      { platform: '69shuba',      lang: 'zh', needs_translation: true,  scraper_type: 'apify' },
  '69shu.com':        { platform: '69shuba',      lang: 'zh', needs_translation: true,  scraper_type: 'apify' },
  'novelbin.com':     { platform: 'novelbin',     lang: 'en', needs_translation: false, scraper_type: 'http'  },
  'freewebnovel.com': { platform: 'freewebnovel', lang: 'en', needs_translation: false, scraper_type: 'http'  },
  'royalroad.com':    { platform: 'royalroad',    lang: 'en', needs_translation: false, scraper_type: 'http'  },
  'wattpad.com':      { platform: 'wattpad',      lang: 'en', needs_translation: false, scraper_type: 'http'  },
  'babelnovel.com':   { platform: 'babelnovel',   lang: 'en', needs_translation: false, scraper_type: 'apify' },
  'tapas.io':         { platform: 'tapas',        lang: 'en', needs_translation: false, scraper_type: 'apify' },
  'wuxiaworld.com':   { platform: 'wuxiaworld',   lang: 'en', needs_translation: false, scraper_type: 'apify' },
  'kakao.com':        { platform: 'kakao',        lang: 'ko', needs_translation: true,  scraper_type: 'apify' },
  'kakaopage.com':    { platform: 'kakao',        lang: 'ko', needs_translation: true,  scraper_type: 'apify' },
  'qidian.com':       { platform: 'qidian',       lang: 'zh', needs_translation: true,  scraper_type: 'apify' },
  'qdmm.com':         { platform: 'qdmm',         lang: 'zh', needs_translation: true,  scraper_type: 'apify' },
  'hengyan.com':      { platform: 'hengyan',      lang: 'zh', needs_translation: true,  scraper_type: 'apify' },
  'ihengyan.com':     { platform: 'hengyan',      lang: 'zh', needs_translation: true,  scraper_type: 'apify' }
};

const config = PLATFORMS[host];
if (!config) {
  return [{ json: { status: 'error', error: 'Unsupported platform: ' + host, url: rawUrl, host } }];
}

let bookPageUrl = rawUrl;
try {
  const u = new URL(rawUrl);
  if (config.platform === 'novelbin') {
    const m = u.pathname.match(/\/b\/([^/]+)/);
    if (m) bookPageUrl = 'https://novelbin.com/b/' + m[1];
  }
  if (config.platform === 'freewebnovel') {
    const m = u.pathname.match(/\/novel\/([^/]+)/);
    if (m) bookPageUrl = 'https://freewebnovel.com/novel/' + m[1] + '/';
  }
  if (config.platform === 'royalroad') {
    const m = u.pathname.match(/\/fiction\/(\d+)\/([^/]+)/);
    if (m) bookPageUrl = 'https://www.royalroad.com/fiction/' + m[1] + '/' + m[2];
  }
} catch (e) {}

return [{ json: {
  status: 'ok',
  url: rawUrl,
  book_page_url: bookPageUrl,
  host,
  platform: config.platform,
  source_language: config.lang,
  needs_translation: config.needs_translation,
  scraper_type: config.scraper_type,
  start_chapter: startChapter,
  end_chapter: endChapter,
  batch_size: 100
}}];
